void PictureQuiz_StateDispatcher(void) {
    s32 var_v0 = 1;

    while (var_v0 != 0) {
        switch (var_v0) {
            case 1:
                var_v0 = TrainerCardMenuLoopSpecies();
                break;

            case 2:
                var_v0 = TrainerCardMenuLoopButtons();
                break;

            case 3:
                var_v0 = PictureQuiz_MainLoop();
                break;

            case 4:
                var_v0 = PictureQuiz_MusicFadeLoop();
                break;

            case 5:
                var_v0 = PictureQuiz_ResultsInputLoop();
                break;
        }
    }
}

